// src/components/Sidebar.js
import React, { useState } from "react";
import { NavLink, useNavigate } from "react-router-dom";

function Sidebar({ user, onLogout }) {
  const [collapsed, setCollapsed] = useState(false);
  const navigate = useNavigate();

  function handleLogoClick() {
    navigate("/dashboard");
  }

  return (
    <aside className={`sidebar ${collapsed ? "collapsed" : ""}`}>
      <div className="sidebar-top">
        <button className="sidebar-logo" onClick={handleLogoClick}>
          <span className="sidebar-logo-icon">🔬</span>
          {!collapsed && <span className="sidebar-logo-text">SciHub</span>}
        </button>

        <button
          className="sidebar-toggle"
          onClick={() => setCollapsed((prev) => !prev)}
          aria-label="Toggle sidebar"
        >
          {collapsed ? "›" : "‹"}
        </button>
      </div>

<nav className="sidebar-nav">

  {/* Dashboard */}
  <NavLink
    to="/dashboard"
    className={({ isActive }) =>
      "sidebar-link" + (isActive ? " active" : "")
    }
  >
    <span className="sidebar-icon">🏠</span>
    {!collapsed && <span className="sidebar-label">Dashboard</span>}
  </NavLink>

  {/* RESOURCES DROPDOWN */}
  <div className="sidebar-dropdown">
    <button
      className="sidebar-link sidebar-dropdown-btn"
      onClick={() => setShowResources((prev) => !prev)}
    >
      <span className="sidebar-icon">📚</span>
      {!collapsed && <span className="sidebar-label">Resources</span>}
      {!collapsed && (
        <span className="sidebar-dropdown-arrow">
          {showResources ? "▲" : "▼"}
        </span>
      )}
    </button>

    {/* DROPDOWN CONTENT */}
    {showResources && !collapsed && (
      <div className="sidebar-dropdown-content">
        <NavLink
          to="/resources/natural"
          className={({ isActive }) =>
            "sidebar-sublink" + (isActive ? " active" : "")
          }
        >
          🌿 Natural Science
        </NavLink>

        <NavLink
          to="/resources/social"
          className={({ isActive }) =>
            "sidebar-sublink" + (isActive ? " active" : "")
          }
        >
          🌍 Social Science
        </NavLink>
      </div>
    )}
  </div>

  {/* Tutoring */}
  <NavLink
    to="/schedule"
    className={({ isActive }) =>
      "sidebar-link" + (isActive ? " active" : "")
    }
  >
    <span className="sidebar-icon">📅</span>
    {!collapsed && <span className="sidebar-label">Tutoring</span>}
  </NavLink>

  {/* Games */}
  <NavLink
    to="/games"
    className={({ isActive }) =>
      "sidebar-link" + (isActive ? " active" : "")
    }
  >
    <span className="sidebar-icon">🎮</span>
    {!collapsed && <span className="sidebar-label">Games</span>}
  </NavLink>

  {/* Q&A */}
  <NavLink
    to="/qna"
    className={({ isActive }) =>
      "sidebar-link" + (isActive ? " active" : "")
    }
  >
    <span className="sidebar-icon">💬</span>
    {!collapsed && <span className="sidebar-label">Q &amp; A</span>}
  </NavLink>

  {/* Profile */}
  <NavLink
    to="/profile"
    className={({ isActive }) =>
      "sidebar-link" + (isActive ? " active" : "")
    }
  >
    <span className="sidebar-icon">👤</span>
    {!collapsed && <span className="sidebar-label">Profile</span>}
  </NavLink>

</nav>


      <div className="sidebar-bottom">
        {!collapsed && user && (
          <div className="sidebar-user">
            <div className="sidebar-avatar">
              {user.firstName
                ? user.firstName[0].toUpperCase()
                : (user.name || "S")[0].toUpperCase()}
            </div>
            <div className="sidebar-user-info">
              <p className="sidebar-user-name">
                {user.firstName
                  ? `${user.firstName} ${user.lastName || ""}`.trim()
                  : user.name || "SciHub Student"}
              </p>
              <p className="sidebar-user-email">{user.email}</p>
            </div>
          </div>
        )}

        <button className="sidebar-logout-btn" onClick={onLogout}>
          <span className="sidebar-icon">⏻</span>
          {!collapsed && <span className="sidebar-label">Log out</span>}
        </button>
      </div>
    </aside>
  );
}

export default Sidebar;
